    "title": "بكين وشيآن ويونان: رحلة خاصة لمدة 14 يوماً",
    "metadataDescription": "رحلة خاصة لمدة 14 يوماً: بكين وشيآن ودالي وليجيانغ ومضيق قفزة النمر وشانغريلا. السعر للشخص 4,110 دولارات أمريكية لمجموعة من شخصين أو 2,640 دولاراً أمريكياً لمجموعة من ستة.",
    "eyebrow": "من المدن القديمة إلى مرتفعات شانغريلا",
    "lede": "من بكين وشيآن إلى بلدات يونان القديمة: تبلغ تكلفة هذه الرحلة الخاصة ذات الـ14 يوماً 4,110 دولارات أمريكية للشخص عند سفر شخصين ومشاركة غرفة بسريرين، دون الرحلات الدولية. بعد العاصمتين التاريخيتين، تقودكم دالي وليجيانغ إلى مضيق قفزة النمر ثم شانغريلا على ارتفاع نحو 3,300 متر. الارتفاع جزء أساسي من طبيعة هذا المسار.",
