    "title": "جولة الصين الكبرى مع تشانغجياجيه ونهر اليانغتسي: 21 يوماً في رحلة خاصة",
    "metadataDescription": "21 يوماً في الصين: بكين وشيآن والباندا ونهر لي وتشانغجياجيه ورحلة بحرية 3 ليالٍ على اليانغتسي وشنغهاي. السعر 5,920 دولاراً أمريكياً للشخص عند سفر شخصين.",
    "eyebrow": "ثلاثة أسابيع بين المدن والجبال ونهر اليانغتسي",
    "lede": "بكين وشيآن، وباندا تشنغدو، ونهر لي، وتشانغجياجيه، وثلاث ليالٍ مع اتجاه تيار اليانغتسي: تستغرق جولة الصين الخاصة الكبرى 21 يوماً. تبلغ التكلفة 5,920 دولاراً أمريكياً للشخص عند سفر شخصين ومشاركة غرفة بسريرين وكابينة قياسية بشرفة، دون الرحلات الدولية. تُخصص عدة أيام كاملة للتنقل بين هذه المحطات.",
    "summary": "تتكون الليالي الـ20 من 17 ليلة فندقية مع الإفطار وثلاث ليالٍ في كابينة بشرفة. يشمل السعر مرشدين محليين ومركبات خاصة في أيام الزيارات البرية، والانتقالات، وتذاكر المواقع المذكورة، والقطارات، والرحلات الداخلية، والرحلة النهرية مع الوجبات على متن السفينة. يتغير المرشد بحسب المدينة؛ وعلى متن السفينة يُتبع برنامجها.",
