    "hotelNote": "من أصل 20 ليلة، تقضون 17 ليلة في فنادق بمستوى أربع نجوم، أي 4 ماسات على Trip.com/Ctrip، بغرف بسريرين مع الإفطار: بكين 4، وشيآن 2، وتشنغدو 2، وقويلين 1، ويانغشو 2، ووولينغيوان 2، ومدينة تشانغجياجيه 1، وتشونغتشينغ 1، وشنغهاي 2. وتقضون ثلاث ليالٍ أخرى في كابينة قياسية بشرفة على سفينة لليانغتسي مصنفة خمس نجوم، عادةً من Gold Cruises. قد تكون الشرفة زجاجية مغلقة في أدنى طابق للكبائن. تُؤكد الفنادق والسفينة والكابينة قبل الدفع.",
