        "answer": "تبلغ تكلفة هذه الرحلة الخاصة ذات الـ21 يوماً عبر بكين وشيآن وتشنغدو وقويلين وتشانغجياجيه واليانغتسي وشنغهاي 5,920 دولاراً أمريكياً للشخص عند سفر شخصين ومشاركة غرفة فندقية وكابينة قياسية بشرفة، أي 11,840 دولاراً أمريكياً للمجموع. السعر للشخص 4,370 دولاراً أمريكياً لأربعة مسافرين، و4,010 دولارات أمريكية لستة. يشمل 17 ليلة فندقية مع الإفطار، وثلاث ليالٍ نهرية مع الوجبات على متن السفينة، ورحلة نهر لي، ومرشدين ومركبات خاصة على اليابسة، والتذاكر والقطارات والرحلات الداخلية المذكورة. تتحملون تكلفة الرحلات الدولية والوجبات على اليابسة؛ وقد ترتفع التكلفة الإجمالية في مواعيد الإبحار مرتفعة الطلب. اطلبوا عرضاً للأعداد الأخرى."
