        "answer": "الفترتان من أبريل إلى مايو ومن سبتمبر إلى أكتوبر هما الأنسب، مع أيام أوضح في تشانغجياجيه وحرارة أيسر تحملاً. تعمل سفن اليانغتسي من أواخر فبراير إلى أواخر ديسمبر، لذلك نادراً ما يقيد جدول الإبحار اختيار التواريخ. يُفضل تجنب الأسبوع الأول من مايو والأول من أكتوبر، إذ تزيد العطلات عدد الزوار في محطات عدة."
