    "hotelNote": "تسع ليالٍ في غرف بسريرين مع الإفطار، بفنادق بمستوى أربع نجوم، أي 4 ماسات على Trip.com/Ctrip: بكين 3، وشيآن 2، وقويلين 1، ويانغشو 1، وشنغهاي 2. تُؤكد الفنادق وفئات الغرف قبل الدفع.",
    "serviceNote": "يتوافر لمجموعتكم وحدها مرشد محلي ناطق بالإنجليزية ومركبة في أيام الزيارات فقط. تشمل الخدمات الانتقالات وتذاكر المواقع الرئيسية المذكورة ورحلة نهر لي؛ وتُنقل الأمتعة منفصلةً براً إلى يانغشو. تتنقلون بين المدن بقطار بكين–شيآن بالدرجة الثانية، ورحلتَي شيآن–قويلين وقويلين–شنغهاي بالدرجة الاقتصادية. يتغير المرشد بحسب المدينة. يوصلكم سائق إلى محطة أو مطار المغادرة، ويستقبلكم آخر في الوجهة. يمكن توفير إرشاد بالكورية بالسعر نفسه، حسب التوافر.",
