    "hotelNote": "تقضون الليالي العشر في غرف بسريرين مع الإفطار، بفنادق بمستوى أربع نجوم، أي 4 ماسات على Trip.com/Ctrip: بكين 4، وهانغتشو 2، وسوتشو 1، وشنغهاي 3. تُؤكد الفنادق والغرف المحددة قبل الدفع.",
    "serviceNote": "في أيام الزيارات، يتوافر لمجموعتكم وحدها في كل مدينة مرشد محلي ناطق بالإنجليزية ومركبة. تشمل الخدمات جميع الانتقالات وتذاكر المواقع الرئيسية المذكورة، ومنها قارب البحيرة الغربية وحديقة في سوتشو والبلدة المائية. يكون السفر من بكين إلى هانغتشو ومن هانغتشو إلى سوتشو بالقطار بالدرجة الثانية، ومن سوتشو إلى شنغهاي بمركبة خاصة. يتغير المرشد بين المدن. يوصلكم سائق إلى محطة المغادرة ويستقبلكم آخر في الوجهة. يمكن توفير إرشاد بالكورية بالسعر نفسه، حسب التوافر.",
