    "hotelNote": "اثنتا عشرة ليلة مع الإفطار في غرف بسريرين: شنغهاي 2، ووولينغيوان 2، ومدينة تشانغجياجيه 1، وفنغهوانغ 2، وقويلين 2، ويانغشو 2، وليلة أخيرة في شنغهاي. تكون الفنادق بمستوى أربع نجوم، أي 4 ماسات على Trip.com/Ctrip، حيثما تتوافر هذه الفئة. في فنغهوانغ نؤكد أفضل فندق تقييماً على النهر قبل الدفع.",
    "serviceNote": "في أيام الزيارات، تحصل مجموعتكم على مرشد محلي ناطق بالإنجليزية ومركبة خاصين بها. يشمل السعر الانتقالات وتذاكر المواقع الرئيسية المذكورة: منتزه غابات تشانغجياجيه ومصعد بايلونغ وتلفريك تيانمن ولونغجي. كما يشمل رحلة نهر لي مع نقل الأمتعة منفصلة براً، ورحلة طوف على يولونغ؛ والقطارين السريعين تشانغجياجيه–فنغهوانغ وفنغهوانغ–قويلين؛ والرحلتين الجويتين الاقتصاديتين شنغهاي–تشانغجياجيه وقويلين–شنغهاي. يتغير المرشد بحسب المدينة، ويتولى السائقون انتقالات المحطات والمطارات. يمكن توفير إرشاد بالكورية بالسعر نفسه، حسب التوافر.",
