    "summary": "ستة أيام في شمال شرق الصين: معالم الجليد في هاربين، ويوم للتزلج في يابولي، ثم بلدة الثلج. تقضون الليالي الخمس كلها في الفنادق: ليلتان في هاربين، وليلة في يابولي، وليلة في منطقة بلدة الثلج، وليلة أخيرة في هاربين.",
