    "metadataDescription": "13 يوماً في رحلة خاصة: سور الصين العظيم وجيش التيراكوتا والباندا ونهر لي وشنغهاي. للشخص: 2,580 دولاراً أمريكياً لأربعة مسافرين، و2,090 دولاراً أمريكياً لثمانية؛ الرحلات الجوية الداخلية مشمولة.",
    "eyebrow": "خمس مدن في ثلاثة عشر يوماً، من سور الصين العظيم إلى البوند",
    "lede": "تصعدون بالتلفريك إلى سور الصين العظيم في موتيانيو. وفي شيآن، تشاهدون جيش الإمبراطور الأول من الممرات المطلة على حفر التنقيب. تصلون إلى مركز الباندا مبكراً قبل أن تنام الحيوانات. وتقضون أربع ساعات على نهر لي بين التلال المصورة على ورقة العشرين يواناً، ثم تختتمون الرحلة على البوند. اثنتا عشرة ليلة في فنادق بأربع نجوم مع الإفطار.",
    "summary": "ثلاث ليالٍ في بكين، وليلتان في شيآن، وليلتان في تشنغدو، وثلاث في قويلين، وليلتان في شنغهاي. رحلتان بالقطار فائق السرعة بالدرجة الثانية ورحلتان جويتان بالدرجة الاقتصادية مع قطعة أمتعة مسجلة، ومرشد محلي ناطق بالإنجليزية في كل يوم جولات، ومركبة خاصة، ورسوم الدخول المذكورة، وثماني وجبات غداء. الفنادق بأربع نجوم والإفطار مشمولان؛ ويُؤكَّد السعر الإجمالي كتابةً قبل الدفع.",
